def _links(t):
    """vals[k], left[k], right[k] for the k-th real node in level order (-1 = no child)."""
    pos, c = [], 0
    for x in t:
        if x == -1:
            pos.append(-1)
        else:
            pos.append(c)
            c += 1
    vals = [x for x in t if x != -1]
    left, right = [-1] * c, [-1] * c
    for k in range(c):
        a = 2 * k + 1
        if a < len(t):
            left[k] = pos[a]
        if a + 1 < len(t):
            right[k] = pos[a + 1]
    return vals, left, right


def widestLevel(tree):
    vals, left, right = _links(tree)
    n = len(vals)
    if n == 0:
        return 0
    pos = [0] * n
    depth = [0] * n
    pos[0] = 1
    lo, hi = [], []
    for k in range(n):
        d = depth[k]
        if d == len(lo):
            lo.append(pos[k])
            hi.append(pos[k])
        else:
            hi[d] = pos[k]
        if left[k] != -1:
            pos[left[k]] = 2 * pos[k]
            depth[left[k]] = d + 1
        if right[k] != -1:
            pos[right[k]] = 2 * pos[k] + 1
            depth[right[k]] = d + 1
    return max(h - l + 1 for l, h in zip(lo, hi))
